def roles_and_suppliers(apps, schema_editor):
    from datetime import timedelta

    from django.contrib.auth.management import create_permissions

    for config in apps.get_app_configs():
        config.models_module = True
        create_permissions(config, apps=apps, verbosity=0)
        config.models_module = None
    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    for name, codenames in ROLES.items():
        group, _ = Group.objects.get_or_create(name=name)
        group.permissions.add(*Permission.objects.filter(content_type__app_label="stores", codename__in=codenames))
    # existing receipts: the free-text supplier becomes a Supplier record
    Supplier = apps.get_model("stores", "Supplier")
    StockReceipt = apps.get_model("stores", "StockReceipt")
    by_name = {}
    for r in StockReceipt.objects.exclude(supplier="").order_by("created_at"):
        key = r.supplier.strip().lower()
        if key not in by_name:
            by_name[key] = Supplier.objects.filter(name__iexact=r.supplier.strip()).first() or Supplier.objects.create(name=r.supplier.strip()[:160])
        StockReceipt.objects.filter(pk=r.pk).update(supplier_ref=by_name[key], due_date=r.created_at.date())


